[InitializeOnLoad]public static class InstallWildernessEnemies {
 const string Folder="Assets/Resources/WildernessEnemies",Request="Assets/Editor/CQC/InstallWildernessEnemies.request.txt";
 const string Out="C:/Users/Joshua/Documents/Codex/2026-10-11/ca/outputs/wilderness-enemies";
 static double next;static bool busy;static InstallWildernessEnemies(){EditorApplication.update+=Poll;}
 static void Poll(){if(busy||EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;
 const string cyclopsRequest="Assets/Editor/CQC/InstallCyclops.request.txt";
 if(File.Exists(cyclopsRequest)&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating&&!EditorApplication.isPlayingOrWillChangePlaymode){File.Delete(cyclopsRequest);try{InstallCyclops();}catch(Exception e){File.WriteAllText(Out+"/cyclops-error.txt",e.ToString());Debug.LogException(e);}return;}
 const string flightRequest="Assets/Editor/CQC/ValidateWildernessFlight.request.txt";
 if(File.Exists(flightRequest)&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating&&!EditorApplication.isPlayingOrWillChangePlaymode){File.Delete(flightRequest);try{ValidateFlight();}catch(Exception e){File.WriteAllText(Out+"/flight-error.txt",e.ToString());Debug.LogException(e);}return;}
 const string packRequest="Assets/Editor/CQC/RebuildWildernessPacks.request.txt";
 if(File.Exists(packRequest)&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating&&!EditorApplication.isPlayingOrWillChangePlaymode&&SceneManager.GetActiveScene().name=="MyForest"){File.Delete(packRequest);try{RebuildPacks();}catch(Exception e){File.WriteAllText(Out+"/pack-error.txt",e.ToString());Debug.LogException(e);}return;}
 if(!File.Exists(Request)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().name!="MyForest")return;busy=true;File.Delete(Request);try{Apply();}catch(Exception e){Directory.CreateDirectory(Out);File.WriteAllText(Out+"/install-error.txt",e.ToString());Debug.LogException(e);}finally{busy=false;}}
 public static void BatchApply(){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/MyForest.unity");Apply();}
 [MenuItem("Tools/Enemies/Install Wilderness Flying Enemies")]
 public static void Apply(){Directory.CreateDirectory(Out);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var report=new StringBuilder("Wilderness flying enemies\n");foreach(string gender in new[]{"Male","Female"})ConfigureModel(gender);
 var clips=new[]{"swim_idle_loop_mirrored","sword_attack_mirrored","hit_chest_mirrored","hit_knockback_mirrored"}.Select(ConfigureClip).ToArray();
 var male=MakePrefab("Male");var female=MakePrefab("Female");Verify(male,clips,report);Verify(female,clips,report);Capture(male,female,clips);
 var settings=AssetDatabase.LoadAssetAtPath<WildernessEnemySettings>(Folder+"/Settings.asset");if(!settings){settings=ScriptableObject.CreateInstance<WildernessEnemySettings>();AssetDatabase.CreateAsset(settings,Folder+"/Settings.asset");}
 settings.Male=male;settings.Female=female;settings.Hover=clips[0];settings.Attack=clips[1];settings.Hit=clips[2];settings.Knockback=clips[3];settings.MagicMaterial=Solid("FairyMagic",new Color(.4f,.7f,1.8f),false);settings.SwordMaterial=Solid("FairySword",new Color(.65f,.75f,.8f),true);
 var zones=CityBounds();var points=Spawns(zones,report);if(points.Length<8)throw new InvalidOperationException("Fewer than eight safe outside-city spawn points; enemies not enabled.");settings.CitySafeZones=zones;settings.SpawnPoints=points;
 settings.MoveSpeed=9;settings.Health=130;settings.AttackDamage=14;settings.AggroDistance=24;settings.LeashDistance=42;settings.RespawnSeconds=50;EditorUtility.SetDirty(settings);AssetDatabase.SaveAssets();
 report.AppendLine("Male/female models: 26 bones including four wing controls, 22000 triangles each, normalized skin weights. Either gender can be mage or sword. Mirrored attack uses LEFT hand.");report.AppendLine("100 fast flying enemies in 22 packs, speed 9m/s, maximum three simultaneous attacks, single aimed bolts or basic sword strikes, hover/hit/knockback clips supplied by user. Existing sword/greatsword/bow/unarmed damage interface supported. Rolling evades damage.");report.AppendLine("Runtime creates one Wilderness Flying Enemies group in MyForest only. City exclusion zones, 18m spawn protection and 42m home leash prevent city pursuit. No city scene geometry changed.");
 File.WriteAllText(Out+"/install-report.txt",report.ToString());Debug.Log("WILDERNESS_ENEMIES_READY\n"+report);}
 static HumanDescription Description(GameObject reference,bool ue,string rootName){var pairs=new Dictionary<HumanBodyBones,string>();foreach(var bone in new[]{HumanBodyBones.Hips,HumanBodyBones.Spine,HumanBodyBones.Chest,HumanBodyBones.UpperChest,HumanBodyBones.Neck,HumanBodyBones.Head})pairs[bone]=ue?new Dictionary<HumanBodyBones,string>{{HumanBodyBones.Hips,"pelvis"},{HumanBodyBones.Spine,"spine_01"},{HumanBodyBones.Chest,"spine_02"},{HumanBodyBones.UpperChest,"spine_03"},{HumanBodyBones.Neck,"neck_01"},{HumanBodyBones.Head,"Head"}}[bone]:bone.ToString();
 foreach(var side in new[]{"Left","Right"})foreach(var part in new[]{"Shoulder","UpperArm","LowerArm","Hand","UpperLeg","LowerLeg","Foot","Toes"}){var bone=(HumanBodyBones)Enum.Parse(typeof(HumanBodyBones),side+part);var src=new Dictionary<string,string>{{"Shoulder","clavicle"},{"UpperArm","upperarm"},{"LowerArm","lowerarm"},{"Hand","hand"},{"UpperLeg","thigh"},{"LowerLeg","calf"},{"Foot","foot"},{"Toes","ball"}};pairs[bone]=ue?src[part]+(side=="Left"?"_l":"_r"):side+"_"+part;}
 var skeleton=reference.GetComponentsInChildren<Transform>(true).Select(t=>new SkeletonBone{name=t.name,position=t.localPosition,rotation=t.localRotation,scale=t.localScale}).ToArray();skeleton[0].name=rootName;
 return new HumanDescription{human=pairs.Select(p=>new HumanBone{humanName=HumanTrait.BoneName[(int)p.Key],boneName=p.Value,limit=new HumanLimit{useDefaultValues=true}}).ToArray(),skeleton=skeleton,armStretch=.02f,legStretch=.02f,upperArmTwist=.5f,lowerArmTwist=.5f,upperLegTwist=.5f,lowerLegTwist=.5f,hasTranslationDoF=false};}
 static void ConfigureModel(string gender){string path=Folder+"/Models/"+gender+"Fairy.fbx";var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!model)throw new Exception("Missing rigged "+gender+" FBX");var im=(ModelImporter)AssetImporter.GetAtPath(path);im.animationType=ModelImporterAnimationType.Human;im.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;im.humanDescription=Description(model,false,model.name);im.importAnimation=false;im.importCameras=im.importLights=false;im.materialImportMode=ModelImporterMaterialImportMode.None;im.optimizeGameObjects=false;im.isReadable=true;im.SaveAndReimport();}
 static AnimationClip ConfigureClip(string name){string path=Folder+"/Animations/"+name+".fbx";var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);var bind=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/Animations/"+name+"_Bind.fbx");if(!model||!bind)throw new Exception("Animation or neutral bind reference missing: "+name);var im=(ModelImporter)AssetImporter.GetAtPath(path);im.animationType=ModelImporterAnimationType.Human;im.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;im.humanDescription=Description(bind,true,model.name);im.materialImportMode=ModelImporterMaterialImportMode.None;im.importCameras=im.importLights=false;im.animationCompression=ModelImporterAnimationCompression.Off;im.importAnimation=true;float frames=name.Contains("heavy_combo")?260:name.Contains("zombie_idle")||name.Contains("walk_fwd")?80:name.Contains("scratch")?108:name.Contains("idle")?200:name.Contains("sword")?92:name.Contains("chest")?20:50;bool loop=name.Contains("idle")||name.Contains("walk_fwd");
 im.clipAnimations=new[]{new ModelImporterClipAnimation{name=name,takeName=im.defaultClipAnimations[0].takeName,firstFrame=0,lastFrame=frames,loopTime=loop,loopPose=loop,lockRootRotation=true,keepOriginalOrientation=true,lockRootHeightY=true,keepOriginalPositionY=false,heightFromFeet=true,lockRootPositionXZ=false,keepOriginalPositionXZ=false}};im.SaveAndReimport();return AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview__"));}
 static Material Solid(string name,Color color,bool lit){string path=Folder+"/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find(lit?"Universal Render Pipeline/Lit":"Universal Render Pipeline/Unlit"));AssetDatabase.CreateAsset(mat,path);}mat.color=color;if(lit){mat.SetFloat("_Metallic",.65f);mat.SetFloat("_Smoothness",.6f);}EditorUtility.SetDirty(mat);return mat;}
 static GameObject MakePrefab(string gender){string folder=Folder+"/Models/";Texture2D Tex(string name,bool normal=false,bool linear=false){string p=folder+gender+"_"+name+".png";var ti=(TextureImporter)AssetImporter.GetAtPath(p);if(ti==null)return null;ti.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=!normal&&!linear;ti.maxTextureSize=name=="Albedo"?2048:1024;ti.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(p);}
 var mat=Solid(gender+"FairySkin",Color.white,true);mat.SetTexture("_BaseMap",Tex("Albedo"));mat.SetTexture("_BumpMap",Tex("Normal",true));mat.EnableKeyword("_NORMALMAP");mat.SetTexture("_MetallicGlossMap",Tex("MetalSmooth",false,true));mat.EnableKeyword("_METALLICSPECGLOSSMAP");mat.SetFloat("_Metallic",1);mat.SetFloat("_Smoothness",.65f);mat.SetFloat("_Cull",0);mat.enableInstancing=true;
 var root=new GameObject(gender+" Wilderness Fairy");try{var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(folder+gender+"Fairy.fbx"),root.transform);var animator=model.GetComponentInChildren<Animator>();if(!animator||!animator.avatar||!animator.avatar.isValid||!animator.avatar.isHuman)throw new Exception("Invalid fairy avatar "+gender);animator.applyRootMotion=false;animator.runtimeAnimatorController=null;foreach(var renderer in model.GetComponentsInChildren<SkinnedMeshRenderer>()){renderer.sharedMaterials=Enumerable.Repeat(mat,renderer.sharedMesh.subMeshCount).ToArray();renderer.updateWhenOffscreen=true;}return PrefabUtility.SaveAsPrefabAsset(root,Folder+"/"+gender+"Fairy.prefab");}finally{UnityEngine.Object.DestroyImmediate(root);}}
 static Bounds[] CityBounds(){var list=new List<Bounds>();foreach(string name in new[]{"Lower Castle City","Castle Mountain"}){var root=GameObject.Find(name);if(!root)continue;var renderers=root.GetComponentsInChildren<Renderer>().Where(r=>r.gameObject.activeInHierarchy).ToArray();if(renderers.Length==0)continue;Bounds b=renderers[0].bounds;foreach(var r in renderers.Skip(1))b.Encapsulate(r.bounds);b.Expand(new Vector3(20,0,20));list.Add(b);}if(list.Count<1)throw new Exception("Cannot locate city boundaries; refusing wilderness placement.");return list.ToArray();}
 static Vector3[] Spawns(Bounds[] zones,StringBuilder report){
 var terrains=Terrain.activeTerrains;if(terrains.Length==0)throw new Exception("No terrain for wilderness spawns");
 var player=GameObject.Find("PlayerArmature");var random=new System.Random(72913);var points=new List<Vector3>();var centers=new List<Vector3>();
 bool Safe(Vector3 p,out Vector3 ground){ground=p;var t=terrains.FirstOrDefault(t=>p.x>=t.transform.position.x&&p.x<=t.transform.position.x+t.terrainData.size.x&&p.z>=t.transform.position.z&&p.z<=t.transform.position.z+t.terrainData.size.z);if(!t)return false;
 var o=t.transform.position;var size=t.terrainData.size;ground.y=t.SampleHeight(p)+o.y;float u=(p.x-o.x)/size.x,v=(p.z-o.z)/size.z;
 if(zones.Any(b=>p.x>=b.min.x&&p.x<=b.max.x&&p.z>=b.min.z&&p.z<=b.max.z)||t.terrainData.GetSteepness(u,v)>30)return false;
 if(player&&(Vector3.Distance(player.transform.position,ground)<32||ground.y>player.transform.position.y+25))return false;
 return !Physics.OverlapSphere(ground+Vector3.up*.9f,.65f,~0,QueryTriggerInteraction.Ignore).Any(c=>!(c is TerrainCollider));}
 for(int attempt=0;attempt<50000&&centers.Count<22;attempt++){
 var t=terrains[random.Next(terrains.Length)];var o=t.transform.position;var size=t.terrainData.size;
 var candidate=new Vector3(o.x+(.06f+(float)random.NextDouble()*.88f)*size.x,0,o.z+(.06f+(float)random.NextDouble()*.88f)*size.z);
 if(centers.Any(q=>Vector3.ProjectOnPlane(q-candidate,Vector3.up).magnitude<42)||!Safe(candidate,out var center))continue;
 int count=centers.Count<10?4:5;var pack=new List<Vector3>();float phase=(float)random.NextDouble()*Mathf.PI*2;
 for(int trial=0;trial<100&&pack.Count<count;trial++){
 float angle=phase+trial*2.399963f;float radius=3f+(trial%5)*.75f;var point=center+new Vector3(Mathf.Sin(angle)*radius,0,Mathf.Cos(angle)*radius);
 if(!Safe(point,out var ground)||Mathf.Abs(ground.y-center.y)>2||pack.Any(q=>Vector3.Distance(q,ground)<2.4f))continue;pack.Add(ground);}
 if(pack.Count!=count)continue;report.AppendLine("Pack "+(centers.Count+1)+": "+count+" enemies around "+center);centers.Add(center);points.AddRange(pack);}
 if(centers.Count!=22||points.Count!=100)throw new InvalidOperationException("Could not fit all 22 safe packs; existing population retained.");
 foreach(var b in zones)report.AppendLine("City protected bounds: "+b);report.AppendLine("Verified 100 enemies in 22 complete packs: ten packs of four and twelve packs of five.");return points.ToArray();}
 public static void RebuildPacks(){var settings=AssetDatabase.LoadAssetAtPath<WildernessEnemySettings>(Folder+"/Settings.asset");if(!settings)throw new Exception("Missing wilderness settings");var report=new StringBuilder();var zones=CityBounds();var points=Spawns(zones,report);settings.CitySafeZones=zones;settings.SpawnPoints=points;EditorUtility.SetDirty(settings);AssetDatabase.SaveAssets();File.WriteAllText(Out+"/pack-report.txt",report.ToString());Debug.Log("WILDERNESS_PACKS_READY: "+report);}
 [MenuItem("Tools/Enemies/Install Cyclops In Packs")]
 public static void InstallCyclops(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var report=new StringBuilder("Cyclops pack integration\n");string path=Folder+"/Models/Cyclops.fbx";var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!model)throw new Exception("Cyclops model missing");var im=(ModelImporter)AssetImporter.GetAtPath(path);im.animationType=ModelImporterAnimationType.Human;im.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;im.humanDescription=Description(model,false,model.name);im.importAnimation=false;im.materialImportMode=ModelImporterMaterialImportMode.None;im.optimizeGameObjects=false;im.isReadable=true;im.SaveAndReimport();
 var clips=new[]{"zombie_idle_loop_mirrored","zombie_walk_fwd_loop_mirrored","sword_attack_mirrored(1)","zombie_scratch_mirrored","sword_heavy_combo_mirrored"}.Select(ConfigureClip).ToArray();
 Material Skin(string prefix){var mat=Solid(prefix+"Skin",Color.white,true);string tex=Folder+"/Models/"+prefix+"_Albedo.png";mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(tex));string normal=Folder+"/Models/"+prefix+"_Normal.png";var ni=AssetImporter.GetAtPath(normal) as TextureImporter;if(ni){ni.textureType=TextureImporterType.NormalMap;ni.SaveAndReimport();mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(normal));mat.EnableKeyword("_NORMALMAP");}mat.SetFloat("_Metallic",0);mat.SetFloat("_Smoothness",.25f);mat.SetFloat("_Cull",0);mat.enableInstancing=true;return mat;}
 var skin=Skin("Cyclops");var clubSkin=Skin("CyclopsClub");GameObject SaveModel(string source,string name,Material mat){var root=new GameObject(name);try{var instance=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(source),root.transform);foreach(var renderer in instance.GetComponentsInChildren<Renderer>())renderer.sharedMaterials=Enumerable.Repeat(mat,renderer.sharedMaterials.Length).ToArray();return PrefabUtility.SaveAsPrefabAsset(root,Folder+"/"+name+".prefab");}finally{UnityEngine.Object.DestroyImmediate(root);}}
 var prefab=SaveModel(path,"Cyclops",skin);var club=SaveModel(Folder+"/Models/CyclopsClub.fbx","CyclopsClub",clubSkin);Verify(prefab,clips,report);
 var settings=AssetDatabase.LoadAssetAtPath<WildernessEnemySettings>(Folder+"/Settings.asset");if(!settings||settings.SpawnPoints.Length!=100)throw new Exception("Expected existing 100-enemy pack settings");settings.Cyclops=prefab;settings.CyclopsClub=club;settings.CyclopsIdle=clips[0];settings.CyclopsWalk=clips[1];settings.CyclopsSwing=clips[2];settings.CyclopsScratch=clips[3];settings.CyclopsCombo=clips[4];EditorUtility.SetDirty(settings);AssetDatabase.SaveAssets();Capture(settings.Male,prefab,new[]{clips[0]},0,"Cyclops-Unity.png");
 settings.CyclopsHeight=3f;settings.CyclopsClubLength=1.65f;EditorUtility.SetDirty(settings);AssetDatabase.SaveAssets();report.AppendLine("22 grounded cyclopes, one per pack; 78 flying fairies; total 100. Club attached to mirrored left hand. Idle, walk, swing, scratch, heavy combo. Health 420, chase speed 6m/s, basic damage 30, combo 20 per strike. Cities and original terrain untouched.");File.WriteAllText(Out+"/cyclops-report.txt",report.ToString());Debug.Log("CYCLOPS_READY: "+report);}
 public static void ValidateFlight(){var settings=AssetDatabase.LoadAssetAtPath<WildernessEnemySettings>(Folder+"/Settings.asset");if(!settings||!settings.Ready)throw new Exception("Missing fairy settings");var report=new StringBuilder();foreach(var prefab in new[]{settings.Male,settings.Female}){var holder=new GameObject("Flight validation");try{var model=UnityEngine.Object.Instantiate(prefab,holder.transform);var pose=holder.AddComponent<WildernessFlightPose>();pose.Initialize(model.transform,model.GetComponentInChildren<Animator>());holder.transform.position+=Vector3.forward*9;pose.Evaluate(true,false,0,1);if(pose.MovementBlend<.99f||Quaternion.Angle(model.transform.localRotation,Quaternion.identity)<20)throw new Exception("Chase flight pose failed");pose.Evaluate(false,false,0,.016f);if(Quaternion.Angle(model.transform.localRotation,Quaternion.identity)>.01f)throw new Exception("Attack flight release failed");report.AppendLine(prefab.name+": chase lean, animated legs, movement blend and attack release passed");}finally{UnityEngine.Object.DestroyImmediate(holder);}}
 Capture(settings.Male,settings.Female,new[]{settings.Hover},2,"Flight-Patrol.png");Capture(settings.Male,settings.Female,new[]{settings.Hover},9,"Flight-Chase.png");File.WriteAllText(Out+"/flight-test.txt",report.ToString());Debug.Log("WILDERNESS_FLIGHT_READY: "+report);}
 static void Verify(GameObject prefab,AnimationClip[] clips,StringBuilder report){var clone=UnityEngine.Object.Instantiate(prefab);PlayableGraph graph=default;try{var a=clone.GetComponentInChildren<Animator>();a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.Rebind();foreach(var clip in clips){graph=PlayableGraph.Create("Fairy rig verification");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,clip);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"fairy",a).SetSourcePlayable(p);graph.Play();var hand=a.GetBoneTransform(HumanBodyBones.LeftHand);Vector3 before=hand.position;float travel=0;for(int i=0;i<30;i++){p.SetTime(clip.length*i/30);graph.Evaluate(1f/60);var h=hand.position;if(!float.IsFinite(h.x)||h.magnitude>5)throw new Exception("Invalid fairy retarget "+clip.name);travel+=Vector3.Distance(before,h);before=h;}if(travel<.03f)throw new Exception("Static fairy hand: "+clip.name);report.AppendLine(prefab.name+" / "+clip.name+": avatar valid, left hand travel="+travel.ToString("F3")+"m");graph.Destroy();a.Rebind();}}finally{if(graph.IsValid())graph.Destroy();UnityEngine.Object.DestroyImmediate(clone);}}
 static void Capture(GameObject male,GameObject female,AnimationClip[] clips,float flightSpeed=0,string imageName="FlyingFairies-Unity.png"){var preview=new PreviewRenderUtility();PlayableGraph graph=default;try{var models=new[]{UnityEngine.Object.Instantiate(male),UnityEngine.Object.Instantiate(female)};for(int i=0;i<2;i++){models[i].transform.position=new Vector3(i==0?1:-1,0,0);preview.AddSingleGO(models[i]);}graph=PlayableGraph.Create("Fairy paired preview");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);for(int i=0;i<2;i++){var a=models[i].GetComponentInChildren<Animator>();a.cullingMode=AnimatorCullingMode.AlwaysAnimate;var p=AnimationClipPlayable.Create(graph,clips[0]);p.SetTime(.8);p.SetSpeed(0);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"fairy "+i,a).SetSourcePlayable(p);}graph.Play();graph.Evaluate(.001f);
 if(flightSpeed>0)foreach(var model in models){var holder=new GameObject("Flight pose test");SceneManager.MoveGameObjectToScene(holder,model.scene);holder.transform.position=model.transform.position;model.transform.SetParent(holder.transform,true);var pose=holder.AddComponent<WildernessFlightPose>();pose.Initialize(model.transform,model.GetComponentInChildren<Animator>());holder.transform.position+=Vector3.forward*flightSpeed;pose.Evaluate(true,false,0,1);holder.transform.position-=Vector3.forward*flightSpeed;model.transform.SetParent(null,true);UnityEngine.Object.DestroyImmediate(holder);preview.AddSingleGO(model);}
 preview.camera.transform.position=new Vector3(0,1.7f,6);preview.camera.transform.LookAt(new Vector3(0,.9f,0));preview.camera.fieldOfView=40;preview.camera.nearClipPlane=.05f;preview.camera.farClipPlane=30;preview.lights[0].intensity=2;preview.lights[0].transform.rotation=Quaternion.Euler(30,210,0);preview.lights[1].intensity=1.5f;
 var temporary=new List<GameObject>();var meshes=new List<Mesh>();foreach(var model in models)foreach(var skin in model.GetComponentsInChildren<SkinnedMeshRenderer>()){var m=new Mesh();skin.BakeMesh(m,true);meshes.Add(m);var go=new GameObject("Frozen fairy pose");go.transform.SetParent(skin.transform,false);go.AddComponent<MeshFilter>().sharedMesh=m;go.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;temporary.Add(go);skin.enabled=false;}
 preview.BeginPreview(new Rect(0,0,1000,650),GUIStyle.none);preview.Render(true);var rt=(RenderTexture)preview.EndPreview();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1000,650,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1000,650),0,0);image.Apply();File.WriteAllBytes(Out+"/"+imageName,image.EncodeToPNG());RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(image);foreach(var go in temporary)UnityEngine.Object.DestroyImmediate(go);foreach(var m in meshes)UnityEngine.Object.DestroyImmediate(m);
 }finally{if(graph.IsValid())graph.Destroy();preview.Cleanup();}}
}}
